<script setup>
import { onMounted, reactive, ref } from 'vue'; import { ElMessage, ElMessageBox } from 'element-plus'; import { api } from '../../lib/api.js'; import { hasPermission } from '../../lib/auth.js'
const rows=ref([]),dialog=ref(false),editing=ref(null),flat=ref([]); const form=reactive({parentId:null,categoryCode:'',categoryName:'',sortOrder:0,status:true});
function flatten(a,r=[]){a.forEach(x=>{r.push(x);flatten(x.children||[],r)});return r} async function load(){try{rows.value=await api.categories();flat.value=flatten(rows.value)}catch(e){ElMessage.error(e.message)}} function open(x=null){editing.value=x?.id||null;Object.assign(form,x?{parentId:x.parentId,categoryCode:x.categoryCode,categoryName:x.categoryName,sortOrder:x.sortOrder,status:x.status}:{parentId:null,categoryCode:'',categoryName:'',sortOrder:0,status:true});dialog.value=true} async function save(){try{editing.value?await api.updateCategory(editing.value,form):await api.createCategory(form);dialog.value=false;await load();ElMessage.success('保存成功')}catch(e){ElMessage.error(e.message)}} async function toggle(x){try{await ElMessageBox.confirm(`确认${x.status?'停用':'启用'}该分类吗？`);await api.categoryStatus(x.id,!x.status);await load()}catch(e){if(e!=='cancel')ElMessage.error(e.message)}} onMounted(load)
</script>
<template><div class="page-heading"><div><h1>物资分类</h1><p class="muted">维护无限层级分类。</p></div><el-button v-if="hasPermission('system.category.create')" type="primary" @click="open()">新增分类</el-button></div><el-card><el-table :data="rows" row-key="id" default-expand-all><el-table-column prop="categoryName" label="分类名称"/><el-table-column prop="categoryCode" label="编号"/><el-table-column prop="sortOrder" label="排序"/><el-table-column label="状态"><template #default="{row}"><el-tag :type="row.status?'success':'info'">{{row.status?'启用':'停用'}}</el-tag></template></el-table-column><el-table-column label="操作"><template #default="{row}"><el-button v-if="hasPermission('system.category.update')" link @click="open(row)">编辑</el-button><el-button v-if="hasPermission('system.category.disable')" link @click="toggle(row)">{{row.status?'停用':'启用'}}</el-button></template></el-table-column></el-table></el-card><el-dialog v-model="dialog" :title="editing?'编辑分类':'新增分类'"><el-form label-width="90px"><el-form-item label="上级分类"><el-select v-model="form.parentId" clearable><el-option v-for="x in flat.filter(x=>x.id!==editing)" :key="x.id" :label="x.categoryName" :value="x.id"/></el-select></el-form-item><el-form-item label="编号"><el-input v-model="form.categoryCode"/></el-form-item><el-form-item label="名称"><el-input v-model="form.categoryName"/></el-form-item><el-form-item label="排序"><el-input-number v-model="form.sortOrder" :min="0"/></el-form-item><el-form-item label="状态"><el-switch v-model="form.status"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></template>
